// CeWire.swift: generated by ce-wire-gen --lang swift. The shared runtime every generated `<Api>.swift` uses: postcard
// codec, ce-wire framing, ce-gate Hello proof, client plumbing. Foundation + Network + CryptoKit, no packages. Do not edit.
import CryptoKit
import Foundation
import Network

public enum CeWire {
public static let deadline: TimeInterval = 1.0 // net.mesh failover stalls 0.84-1.9 s, then the caller reconnects
/// How long a call waits for its answer (Leif 2026-11-07 12:25 CST: "it cant fail in under a second it needs to keep trying"); dialing keeps `deadline`.
public static let callDeadline: TimeInterval = 8.0
public static let doorPort: UInt16 = 7700
static let header = 17
static let maxPayload = 16 << 20
static let kHello: UInt8 = 0, kReq: UInt8 = 1, kResp: UInt8 = 2, kErr: UInt8 = 3, kSub: UInt8 = 5, kItem: UInt8 = 6, kEnd: UInt8 = 7

public enum WireError: Error, CustomStringConvertible {
    case timeout(String)
    case closed
    case decode(String)
    case encode(String)
    case io(String)
    /// The server said no. kind: Schema | Gate | Right | UnknownOp | NoCell | Decode | Remote | SchemaAt | Adapt | SchemaMismatch.
    case refused(kind: String, detail: String)
    public var description: String {
        switch self {
        case .timeout(let s): return "timeout: \(s)"
        case .closed: return "connection closed"
        case .decode(let s): return "decode: \(s)"
        case .encode(let s): return "encode: \(s)"
        case .io(let s): return "io: \(s)"
        case .refused(let k, let d): return d.isEmpty ? "refused: \(k)" : "refused: \(k): \(d)"
        }
    }
}

/// `Result<T, E>` on the wire: postcard enum, variant 0 = ok, 1 = err.
public enum WireResult<T, E> {
    case ok(T)
    case err(E)
}

public final class W {
    public var buf = Data()
    public init() {}
    public func byte(_ b: UInt8) { buf.append(b) }
    public func raw(_ d: Data) { buf.append(d) }
    public func varint(_ v: UInt64) {
        var v = v
        while v >= 0x80 {
            buf.append(UInt8(v & 0x7f) | 0x80)
            v >>= 7
        }
        buf.append(UInt8(v))
    }
    public func zigzag(_ v: Int64) { varint(UInt64(bitPattern: (v << 1) ^ (v >> 63))) }
    public func f32(_ v: Float) { withUnsafeBytes(of: v.bitPattern.littleEndian) { buf.append(contentsOf: $0) } }
    public func f64(_ v: Double) { withUnsafeBytes(of: v.bitPattern.littleEndian) { buf.append(contentsOf: $0) } }
    public func str(_ s: String) { bytes(Data(s.utf8)) }
    public func bytes(_ d: Data) {
        varint(UInt64(d.count))
        buf.append(d)
    }
    public func fixed(_ d: Data, _ n: Int) throws {
        guard d.count == n else { throw WireError.encode("expected \(n) bytes, got \(d.count)") }
        buf.append(d)
    }
    public func count(_ c: Int, _ n: Int) throws {
        guard c == n else { throw WireError.encode("expected \(n) items, got \(c)") }
    }
    func le64(_ v: UInt64) { withUnsafeBytes(of: v.littleEndian) { buf.append(contentsOf: $0) } }
    func le32(_ v: UInt32) { withUnsafeBytes(of: v.littleEndian) { buf.append(contentsOf: $0) } }
}

public final class R {
    let b: [UInt8]
    var i = 0
    public init(_ d: Data) { b = [UInt8](d) }
    public var atEnd: Bool { i == b.count }
    public func take(_ n: Int) throws -> Data {
        guard n >= 0, i + n <= b.count else { throw WireError.decode("unexpected end of data") }
        defer { i += n }
        return Data(b[i..<(i + n)])
    }
    public func byte() throws -> UInt8 {
        guard i < b.count else { throw WireError.decode("unexpected end of data") }
        defer { i += 1 }
        return b[i]
    }
    public func varint() throws -> UInt64 {
        var x: UInt64 = 0
        var sh: UInt64 = 0
        for _ in 0..<10 {
            let c = try byte()
            x |= UInt64(c & 0x7f) << sh
            if c & 0x80 == 0 { return x }
            sh += 7
        }
        throw WireError.decode("varint too long")
    }
    public func uint<T: FixedWidthInteger & UnsignedInteger>(_: T.Type) throws -> T {
        let v = try varint()
        guard let t = T(exactly: v) else { throw WireError.decode("\(T.self) overflow") }
        return t
    }
    public func sint<T: FixedWidthInteger & SignedInteger>(_: T.Type) throws -> T {
        let z = try varint()
        let v = Int64(bitPattern: (z >> 1) ^ (0 &- (z & 1)))
        guard let t = T(exactly: v) else { throw WireError.decode("\(T.self) overflow") }
        return t
    }
    public func len() throws -> Int {
        let n = try varint()
        guard n <= UInt64(maxPayload) else { throw WireError.decode("length too long") }
        return Int(n)
    }
    public func f32() throws -> Float { Float(bitPattern: UInt32(littleEndian: try le(4))) }
    public func f64() throws -> Double { Double(bitPattern: try le(8)) }
    func le<T: FixedWidthInteger>(_ n: Int) throws -> T {
        let d = try take(n)
        var v: T = 0
        for (k, c) in d.enumerated() { v |= T(c) << (8 * k) }
        return v
    }
    public func bool() throws -> Bool {
        switch try byte() {
        case 0: return false
        case 1: return true
        default: throw WireError.decode("bad bool")
        }
    }
    public func str() throws -> String {
        guard let s = String(data: try bytes(), encoding: .utf8) else { throw WireError.decode("bad utf-8") }
        return s
    }
    public func bytes() throws -> Data { try take(try len()) }
    public func vec<T>(_ f: (R) throws -> T) throws -> [T] {
        let n = try len()
        var o: [T] = []
        o.reserveCapacity(min(n, 1024))
        for _ in 0..<n { o.append(try f(self)) }
        return o
    }
    public func arr<T>(_ n: Int, _ f: (R) throws -> T) throws -> [T] {
        var o: [T] = []
        for _ in 0..<n { o.append(try f(self)) }
        return o
    }
    public func opt<T>(_ f: (R) throws -> T) throws -> T? {
        switch try byte() {
        case 0: return nil
        case 1: return try f(self)
        default: throw WireError.decode("bad option tag")
        }
    }
    public func res<T, E>(_ ok: (R) throws -> T, _ err: (R) throws -> E) throws -> WireResult<T, E> {
        switch try varint() {
        case 0: return .ok(try ok(self))
        case 1: return .err(try err(self))
        default: throw WireError.decode("bad result tag")
        }
    }
}

public protocol WireType {
    func enc(_ w: W) throws
    static func dec(_ r: R) throws -> Self
}

static func decodeAll<T>(_ body: Data, _ f: (R) throws -> T) throws -> T {
    let r = R(body)
    let v = try f(r)
    guard r.atEnd else { throw WireError.decode("trailing bytes") }
    return v
}

static func frame(_ kind: UInt8, _ id: UInt64, _ op: UInt32, _ payload: Data = Data()) -> Data {
    let w = W()
    w.le32(UInt32(payload.count))
    w.byte(kind)
    w.le64(id)
    w.le32(op)
    w.raw(payload)
    return w.buf
}

/// proto.rs `Refusal`, variant order fixed. Ok carries the session id.
static func refusal(_ body: Data) -> Result<UInt64, WireError> {
    do {
        let r = R(body)
        switch try r.varint() {
        case 0: return .success(try r.varint())
        case 1:
            let ours = try r.varint(), theirs = try r.varint(), api = try r.str()
            return .failure(.refused(kind: "Schema", detail: "server has schema 0x\(String(ours, radix: 16)), this client 0x\(String(theirs, radix: 16)) (api \(api))"))
        case 4: return .failure(.refused(kind: "UnknownOp", detail: String(try r.varint())))
        case 8:
            let ours = try r.varint(), theirs = try r.varint(), api = try r.str(), update = try r.str()
            return .failure(.refused(kind: "SchemaAt", detail: "server has schema 0x\(String(ours, radix: 16)), this client 0x\(String(theirs, radix: 16)) (api \(api)): \(update)"))
        case 9:
            // typed adapters (rust-stack docs/SCHEMA-ADAPTERS.md): one op could not be carried between two api versions
            let api = try r.str(), op = try r.varint(), opName = try r.str(), ours = try r.varint(), theirs = try r.varint()
            let why: String
            switch try r.varint() {
            case 0: why = "Narrow field \(try r.str()) value \(try r.str())"
            case 1: why = "NoVariant field \(try r.str()) variant \(try r.str())"
            case 2: why = "Missing field \(try r.str())"
            case 3: why = "NoPath"
            case 4: why = "Decode \(try r.str())"
            case let k: return .failure(.decode("unknown AdaptError variant \(k)"))
            }
            return .failure(.refused(kind: "Adapt", detail: "\(api) op \(opName) (#\(op)) v\(theirs) <-> v\(ours): \(why)"))
        case 10:
            // per-op hash (2.1): the server let this client in op by op, and this op's shape differs on the two sides
            let api = try r.str(), op = try r.varint(), opName = try r.str(), ours = try r.varint(), theirs = try r.varint()
            return .failure(.refused(kind: "SchemaMismatch", detail: "\(api) op \(opName) (#\(op)): server shape 0x\(String(ours, radix: 16)), this client 0x\(String(theirs, radix: 16))"))
        case let i:
            let names: [UInt64: String] = [2: "Gate", 3: "Right", 5: "NoCell", 6: "Decode", 7: "Remote"]
            guard let n = names[i] else { return .failure(.decode("unknown Refusal variant \(i)")) }
            return .failure(.refused(kind: n, detail: try r.str()))
        }
    } catch {
        return .failure(.refused(kind: "Remote", detail: "bad error body"))
    }
}

static func refused(_ body: Data) -> WireError {
    switch refusal(body) {
    case .success: return .refused(kind: "Ok", detail: "")
    case .failure(let e): return e
    }
}

// ---- ce-gate Hello proof (byte-identical to crates/ce-gate: postcard Proof/Signed, bincode ce-cap chain) ----

static let helloDomain = "ce-wire-hello-v1"

/// A ce node key: 32 secret seed bytes. nodeId is the ed25519 public key.
public struct NodeKey: @unchecked Sendable {
    public let key: Curve25519.Signing.PrivateKey
    public var nodeId: Data { key.publicKey.rawRepresentation }
    public init(seed: Data) throws { key = try Curve25519.Signing.PrivateKey(rawRepresentation: seed) }
    public init() { key = Curve25519.Signing.PrivateKey() }
    public var seed: Data { key.rawRepresentation }
    public func sign(_ d: Data) throws -> Data { try key.signature(for: d) }
}

static func bcU64(_ w: W, _ v: UInt64) { w.le64(v) }
static func bcBytes(_ w: W, _ d: Data) {
    w.le64(UInt64(d.count))
    w.raw(d)
}

/// ce_gate::self_chain_in: a one-link ce-cap chain `k` signs for itself (`abilities`, `secs` seconds), as
/// ce_cap::encode_chain_bytes bytes. Only accepted where `k`'s node is a root.
public static func selfChain(_ k: NodeKey, _ abilities: [String], secs: UInt64, pathPrefix: String? = nil) throws -> Data {
    let notAfter = UInt64(Date().timeIntervalSince1970) + secs
    let body = W()
    body.raw(k.nodeId)
    body.raw(k.nodeId)
    bcU64(body, UInt64(abilities.count))
    for a in abilities { bcBytes(body, Data(a.utf8)) }
    body.raw(Data(count: 4)) // Resource::Any
    bcU64(body, 0) // not_before
    bcU64(body, notAfter)
    body.raw(Data(count: 4)) // max_cpu, max_mem_mb, max_credits, allowed_ports: None
    if let p = pathPrefix {
        body.byte(1)
        bcBytes(body, Data(p.utf8))
    } else { body.byte(0) }
    bcU64(body, UInt64.random(in: 0...UInt64.max))
    body.byte(0) // parent: None
    let s = W()
    bcBytes(s, Data("ce-cap-v1".utf8))
    s.raw(body.buf)
    let sig = try k.sign(s.buf)
    let o = W()
    bcU64(o, 1)
    o.raw(body.buf)
    bcBytes(o, sig)
    return o.buf
}

/// ce_gate::proof_for: the Hello token proving `k` holds `chain` (encode_chain_bytes bytes, e.g. a ce-iam grant
/// decoded from hex) for `api` at `schema`.
public static func proofFor(_ k: NodeKey, chain: Data, api: String, schema: UInt64) throws -> Data {
    let unixMs = UInt64(Date().timeIntervalSince1970 * 1000)
    var nonce = Data(count: 16)
    for i in 0..<16 { nonce[i] = UInt8.random(in: 0...255) }
    let s = W()
    s.str(helloDomain)
    s.str(api)
    s.varint(schema)
    s.varint(unixMs)
    s.raw(nonce)
    s.raw(k.nodeId)
    s.bytes(chain)
    let sig = try k.sign(s.buf)
    let p = W()
    p.raw(k.nodeId)
    p.varint(unixMs)
    p.raw(nonce)
    p.bytes(chain)
    p.bytes(sig)
    return p.buf
}

/// Where and how to say hello. `token` is a proof (proofFor); empty = no proof.
public struct ConnectOpts: Sendable {
    public var host: String
    public var port: UInt16
    public var token: Data
    public var spawn: Bool
    public var wait: TimeInterval
    public init(host: String, port: UInt16 = doorPort, token: Data = Data(), spawn: Bool = false, wait: TimeInterval = deadline) {
        self.host = host
        self.port = port
        self.token = token
        self.spawn = spawn
        self.wait = wait
    }
}

/// One ce-wire connection. All state lives on `q`, the connection's own serial queue.
public final class Conn: @unchecked Sendable {
    let nw: NWConnection
    let q = DispatchQueue(label: "ce-wire.conn")
    var buf = Data()
    var nextId: UInt64 = 1
    var pending: [UInt64: (Result<(UInt8, Data), WireError>) -> Void] = [:]
    var subs: [UInt64: AsyncThrowingStream<Data, Error>.Continuation] = [:]
    var first: ((Result<(UInt8, Data), WireError>) -> Void)?
    var closed = false
    public private(set) var session: UInt64 = 0
    public var deadline: TimeInterval = CeWire.callDeadline

    init(_ nw: NWConnection) { self.nw = nw }

    static func open(_ o: ConnectOpts, hello: Data) async throws -> Conn {
        let p = NWParameters.tcp
        (p.defaultProtocolStack.transportProtocol as? NWProtocolTCP.Options)?.noDelay = true
        (p.defaultProtocolStack.transportProtocol as? NWProtocolTCP.Options)?.connectionTimeout = Int(max(1, o.wait.rounded(.up)))
        guard let port = NWEndpoint.Port(rawValue: o.port) else { throw WireError.io("bad port \(o.port)") }
        let c = Conn(NWConnection(host: NWEndpoint.Host(o.host), port: port, using: p))
        let (kind, body): (UInt8, Data) = try await withCheckedThrowingContinuation { cont in
            c.q.async {
                var done = false
                let finish: (Result<(UInt8, Data), WireError>) -> Void = { r in
                    if done { return }
                    done = true
                    c.first = nil
                    if case .failure = r { c.shut() }
                    cont.resume(with: r)
                }
                c.first = finish
                c.nw.stateUpdateHandler = { st in
                    switch st {
                    case .ready:
                        c.nw.send(content: frame(kHello, 0, 0, hello), completion: .contentProcessed { _ in })
                        c.read()
                    case .failed(let e): finish(.failure(.io("connect \(o.host):\(o.port): \(e)")))
                    case .waiting(let e): finish(.failure(.io("connect \(o.host):\(o.port): \(e)")))
                    case .cancelled: finish(.failure(.closed))
                    default: break
                    }
                }
                c.q.asyncAfter(deadline: .now() + o.wait + 1.0) { finish(.failure(.timeout("no Hello answer from \(o.host):\(o.port)"))) }
                c.nw.start(queue: c.q)
            }
        }
        switch refusal(body) {
        case .success(let s) where kind == kHello:
            c.session = s
            return c
        case .success: c.close(); throw WireError.refused(kind: "Ok", detail: "")
        case .failure(let e): c.close(); throw e
        }
    }

    func read() {
        nw.receive(minimumIncompleteLength: 1, maximumLength: 1 << 16) { [self] d, _, complete, err in
            if let d, !d.isEmpty { feed(d) }
            if complete || err != nil { shut() } else if !closed { read() }
        }
    }

    func feed(_ d: Data) {
        buf.append(d)
        while buf.count >= header {
            let b = [UInt8](buf.prefix(header))
            let len = Int(UInt32(b[0]) | UInt32(b[1]) << 8 | UInt32(b[2]) << 16 | UInt32(b[3]) << 24)
            if len > maxPayload { return shut() }
            guard buf.count >= header + len else { return }
            let kind = b[4]
            var id: UInt64 = 0
            for k in 0..<8 { id |= UInt64(b[5 + k]) << (8 * k) }
            let body = Data(buf.subdata(in: buf.startIndex + header..<buf.startIndex + header + len))
            buf = Data(buf.dropFirst(header + len))
            if let f = first {
                f(.success((kind, body)))
                continue
            }
            if kind == kItem || kind == kEnd || kind == kErr, let s = subs[id] {
                switch kind {
                case kItem: s.yield(body)
                case kEnd: subs[id] = nil; s.finish()
                default: subs[id] = nil; s.finish(throwing: refused(body))
                }
                continue
            }
            if let w = pending.removeValue(forKey: id) { w(.success((kind, body))) }
        }
    }

    func shut() {
        if closed { return }
        closed = true
        nw.cancel()
        first?(.failure(.closed))
        for (_, w) in pending { w(.failure(.closed)) }
        pending.removeAll()
        for (_, s) in subs { s.finish(throwing: WireError.closed) }
        subs.removeAll()
    }

    public func close() { q.async { self.shut() } }

    /// One request, its typed answer decoded by `dec`.
    /// `wait`: the op's own deadline (`deadline_ms` in api!); the call waits the longer of it and `deadline`.
    public func call<T>(_ op: UInt32, _ payload: Data, wait: TimeInterval = 0, _ dec: @escaping (R) throws -> T) async throws -> T {
        let deadline = max(self.deadline, wait)
        let (kind, body): (UInt8, Data) = try await withCheckedThrowingContinuation { cont in
            q.async { [self] in
                if closed { return cont.resume(throwing: WireError.closed) }
                let id = nextId
                nextId += 1
                pending[id] = { cont.resume(with: $0) }
                q.asyncAfter(deadline: .now() + deadline) { [self] in
                    pending.removeValue(forKey: id)?(.failure(.timeout("op \(op) took over \(deadline) s")))
                }
                nw.send(content: frame(kReq, id, op, payload), completion: .contentProcessed { _ in })
            }
        }
        guard kind == kResp else { throw refused(body) }
        return try decodeAll(body, dec)
    }

    /// A server-push stream: raw item bodies; the generated method decodes them. Cancelling the consumer ends it.
    public func subscribe(_ op: UInt32, _ payload: Data) -> AsyncThrowingStream<Data, Error> {
        AsyncThrowingStream { cont in
            q.async { [self] in
                if closed { return cont.finish(throwing: WireError.closed) }
                let id = nextId
                nextId += 1
                subs[id] = cont
                cont.onTermination = { [self] _ in
                    q.async { [self] in
                        if subs.removeValue(forKey: id) != nil, !closed {
                            nw.send(content: frame(kEnd, id, op), completion: .contentProcessed { _ in })
                        }
                    }
                }
                nw.send(content: frame(kSub, id, op, payload), completion: .contentProcessed { _ in })
            }
        }
    }
}

/// Say hello to the door at `o.host:o.port` as api `name`/`version`/`schema`.
public static func connect(_ o: ConnectOpts, api name: String, version: UInt32, schema: UInt64) async throws -> Conn {
    let w = W()
    w.str(name)
    w.varint(UInt64(version))
    w.varint(schema)
    w.bytes(o.token)
    w.byte(o.spawn ? 1 : 0)
    return try await Conn.open(o, hello: w.buf)
}
}

public typealias WireError = CeWire.WireError
public typealias WireResult<T, E> = CeWire.WireResult<T, E>

// --- Link: the client state machine every typed client shares (same states, words and rules as ce_wire::Link in
// Rust and the py / ts runtimes). Leif 2026-10-14 17:35: "auto generate typed clients ... so its typed safe with the
// state machine in all languages".
//   idle -> finding -> live <-> stale ; any failure -> reconnecting (1 s doubling to 20 s) -> finding ;
//   refused (gate, right, schema, unknown op: waiting cannot help) and failed (max_attempts spent) end the link.

public enum LinkState: Equatable, Sendable {
    case idle
    case finding
    case live(sinceMs: UInt64)
    case stale(quietMs: UInt64)
    case reconnecting(attempt: Int, waitMs: UInt64, why: String)
    case refused(why: String)
    case failed(why: String)

    /// One short line for a status bar, the same words in every language.
    public var line: String {
        switch self {
        case .idle: return "idle"
        case .finding: return "finding the cell"
        case .live: return "live"
        case .stale(let q): return "live, nothing for \(q / 1000) s"
        case .reconnecting(let a, let w, let why): return "reconnecting in \((w + 999) / 1000) s (try \(a)): \(why)"
        case .refused(let why): return "refused: \(why)"
        case .failed(let why): return "failed: \(why)"
        }
    }
    public var name: String {
        switch self {
        case .idle: return "idle"
        case .finding: return "finding"
        case .live: return "live"
        case .stale: return "stale"
        case .reconnecting: return "reconnecting"
        case .refused: return "refused"
        case .failed: return "failed"
        }
    }
}

public enum LinkRules {
    public static func retryable(_ e: Error) -> Bool {
        if case CeWire.WireError.refused(let k, _) = e { return !["Gate", "Right", "Schema", "UnknownOp"].contains(k) }
        return true
    }
    /// Milliseconds before try `attempt` (1-based): firstMs doubling, capped at maxMs.
    public static func wait(_ attempt: Int, firstMs: UInt64 = 1000, maxMs: UInt64 = 20000) -> UInt64 {
        min(firstMs << UInt64(min(max(attempt - 1, 0), 20)), maxMs)
    }
}

private func nowMs() -> UInt64 { UInt64(Date().timeIntervalSince1970 * 1000) }

/// One kept-up connection to a cell. `connect` returns a connected client (a generated client's by-name connect or a
/// fixed address); `onState` is called on every move (on the link's task; hop to the main actor for UI).
public final class Link<C>: @unchecked Sendable {
    public private(set) var state: LinkState = .idle
    public var firstWaitMs: UInt64 = 1000, maxWaitMs: UInt64 = 20000, maxAttempts = 0, staleAfterMs: UInt64 = 30000
    let connectFn: () async throws -> C
    let onState: (LinkState) -> Void
    let lock = NSLock()
    var lastItemMs: UInt64 = 0
    public init(connect: @escaping () async throws -> C, onState: @escaping (LinkState) -> Void = { _ in }) {
        connectFn = connect
        self.onState = onState
    }
    func set(_ s: LinkState) {
        lock.lock(); state = s; lock.unlock()
        onState(s)
    }
    // Sync helpers: NSLock is not for async contexts (Swift 6), so the lock is held only inside these.
    func touch() { lock.lock(); lastItemMs = nowMs(); lock.unlock() }
    func quietMs() -> UInt64 { lock.lock(); defer { lock.unlock() }; return nowMs() - lastItemMs }
    /// -> the next attempt number, or nil when the link ended (refused, failed, cancelled).
    func afterError(_ attempt: Int, _ e: Error) async -> Int? {
        let why = "\(e)"
        if !LinkRules.retryable(e) { set(.refused(why: why)); return nil }
        let a = attempt + 1
        if maxAttempts > 0 && a >= maxAttempts { set(.failed(why: "\(a) tries: \(why)")); return nil }
        let w = LinkRules.wait(a, firstMs: firstWaitMs, maxMs: maxWaitMs)
        set(.reconnecting(attempt: a, waitMs: w, why: why))
        do { try await Task.sleep(nanoseconds: w * 1_000_000) } catch { return nil }
        return a
    }
    /// A connected client (state live), or nil (state refused / failed, or the task was cancelled).
    public func connect() async -> C? {
        var attempt = 0
        while !Task.isCancelled {
            set(.finding)
            do {
                let c = try await connectFn()
                set(.live(sinceMs: nowMs()))
                return c
            } catch {
                guard let a = await afterError(attempt, error) else { return nil }
                attempt = a
            }
        }
        return nil
    }
    /// Follow a stream until refused, failed or the task is cancelled: `open(client)` opens it (called on every
    /// reconnect, so a cursor can resume), `onItem` gets each item. -> the final state.
    public func follow<T>(_ open: @escaping (C) throws -> AsyncThrowingStream<T, Error>, close: @escaping (C) -> Void = { _ in },
                          onItem: @escaping (T) -> Void) async -> LinkState {
        var attempt = 0
        while !Task.isCancelled {
            guard let c = await connect() else { return state }
            var err: Error = CeWire.WireError.closed
            touch()
            // Stale watch: no item for staleAfterMs while the stream is open.
            let watch = Task { [self] in
                while !Task.isCancelled {
                    try? await Task.sleep(nanoseconds: staleAfterMs * 1_000_000)
                    if Task.isCancelled { break }
                    let q = quietMs()
                    if q >= staleAfterMs { set(.stale(quietMs: q / staleAfterMs * staleAfterMs)) }
                }
            }
            do {
                for try await item in try open(c) {
                    touch()
                    if case .live = state {} else { set(.live(sinceMs: nowMs())) }
                    attempt = 0
                    onItem(item)
                }
            } catch { err = error }
            watch.cancel()
            close(c)
            if Task.isCancelled { break }
            guard let a = await afterError(attempt, err) else { return state }
            attempt = a
        }
        set(.idle)
        return state
    }
}
